  cin >> n >> m;

  vector<vector<int>> G(n);

  rep(i,m){

    int a,b;

    cin >> a >> b;

    G[a].pb(b);

  }

  vector<int> vs;

  vector<bool> used(n,false);

  function<void(int)> dfs = [&](int v){

    used[v] = true;

    for(int u : G[v]){

      if(!used[u]) dfs(u);

    }

    vs.pb(v);

  };

  rep(i,n){

    if(!used[i]) dfs(i);

  }

  reverse(all(vs));

  vector<bool> used2(n,false);

  vector<vector<int>> ans;

