    used2[v] = true;

    for(int u : G[v]){

      if(!used2[u]) dfs2(u);

    }

    ans.back().pb(v);

  };

  rep(i,n){

    if(!used2[vs[i]]){

      ans.pb(vector<int>());

      dfs2(vs[i]);

    }

  }

  cout << ans.size() << endl;

  for(auto v : ans){

    sort(all(v));

    cout << v.size();

    for(int u : v) cout << " " << u;

    cout << endl;

  }

  return 0;

}

