bool check(ll x) {

    ll sum = 0;

    for (int i = 1; i <= n; i++) {

        sum += abs(a[i] - x);

    }

    return sum <= x;

}

int main() {

    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {

        scanf("%lld", &a[i]);

    }

    sort(a + 1, a + n + 1);

    ll l = 0, r = 1e18;

    while (l < r) {

        ll mid = (l + r) >> 1;

        if (check(mid)) {

            r = mid;

        } else {

            l = mid + 1;

        }

    }

    printf("%lld\n", l);

    return 0;

}

