#include <cstdio>

const int N = 500005;

int head[N], nxt[N << 1], to[N << 1], cnt;

long long cap[N << 1];

void add(int u, int v, long long w) {
    nxt[++cnt] = head[u];
    head[u] = cnt;
    to[cnt] = v;
    cap[cnt] = w;
}

long long dinic(int s, int t, int n) {
    long long ans = 0;
    static int dep[N], cur[N], que[N];
    while (true) {
        for (int i = 1; i <= n; i++) dep[i] = 0;
        dep[s] = 1;
        int l = 1, r = 1;
        que[1] = s;
        while (l <= r) {
            int u = que[l++];
            for (int i = head[u]; i; i = nxt[i]) {
                if (!dep[to[i]] && cap[i]) {
                    dep[to[i]] = dep[u] + 1;
                    que[++r] = to[i];
                }
            }
        }
        if (!dep[t]) break;
        for (int i = 1; i <= n; i++) cur[i] = head[i];
        while (true) {
            int u = que[r--];
            if (u == s) {
                ans += cap[cur[s]];
                continue;
            }
            if (u == t) continue;
            for (int i = cur[u]; i; i = nxt[i]) {
                if (dep[to[i]] == dep[u] + 1 && cap[i]) {
                    cap[i] -= cap[cur[s]];
                    cap[i ^ 1] += cap[cur[s]];
                    cur[u] = i;
                    break;
                }
            }
            if (cur[u]) continue;
            dep[u] = 0;
            for (int i = head[u]; i; i = nxt[i]) {
                if (cap[i] && dep[to[i]]) {
                    dep[u] = dep[to[i]] + 1;
                    break;
                }
            }
            if (dep[u]) continue;
            for (int i = head[u]; i; i = nxt[i]) {
                if (cap[i]) {
                    cap[i ^ 1] += cap[i];
                    cap[i] = 0;
                }
            }
        }
    }
    return ans;
}

int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i++) {
        int u, v;
        long long w;
        scanf("%d%d%lld", &u, &v, &w);
        add(u, v, w);
        add(v, u, 0);
    }
    printf("%lld\n", dinic(1, n, n));
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define rep(i, a, b) for(int i = a; i < (b); ++i)

#define all(x) begin(x), end(x)

#define sz(x) (int)(x).size()

typedef long long ll;

typedef pair<int, int> pii;

typedef vector<int> vi;



/**

 * Author: chilli

 * Date: 2019-04-26

 * License: CC0

 * Source: https://cp-algorithms.com/graph/dinic.html

 * Description: Flow algorithm with complexity $O(VE\log U)$ where $U = \max |\text{cap}|$.

 * $O(\min(E^{1/2}, V^{2/3})E)$ if $U = 1$; $O(\sqrt{V}E)$ for bipartite matching.

 * Status: Tested on SPOJ FASTFLOW and SPOJ MATCHING, stress-tested

 */



struct Dinic {

	struct Edge {

		int to, rev;

		ll c, oc;

		ll flow() { return max(oc - c, 0LL); } // if you need flows

	};

	vi lvl, ptr, q;

	vector<vector<Edge>> adj;

	Dinic(int n) : lvl(n), ptr(n), q(n), adj(n) {}

	void addEdge(int a, int b, ll c, ll rcap = 0) {

		adj[a].push_back({b, sz(adj[b]), c, c});

		adj[b].push_back({a, sz(adj[a]) - 1, rcap, rcap});

	}

	ll dfs(int v, int t, ll f) {

		if (v == t || !f) return f;

		for (int& i = ptr[v]; i < sz(adj[v]); i++) {

			Edge& e = adj[v][i];

			if (lvl[e.to] == lvl[v] + 1)

				if (ll p = dfs(e.to, t, min(f, e.c))) {

					e.c -= p, adj[e.to][e.rev].c += p;

					return p;

				}

		}

		return 0;

	}

	ll calc(int s, int t) {

		ll flow = 0; q[0] = s;

		rep(L,0,31) do { // 'int L=30' maybe faster for random data

			lvl = ptr = vi(sz(q));

			int qi = 0, qe = lvl[s] = 1;

			while (qi < qe && !lvl[t]) {

				int v = q[qi++];

				for (Edge e : adj[v])

					if (!lvl[e.to] && e.c >> (30 - L))

						q[qe++] = e.to, lvl[e.to] = lvl[v] + 1;

			}

			while (ll p = dfs(s, t, LLONG_MAX)) flow += p;

		} while (lvl[t]);

		return flow;

	}

	bool leftOfMinCut(int a) { return lvl[a] != 0; }

};



int main() {

  int n, m; cin >> n >> m;

  Dinic d(n);

  for (int i = 0; i < m; i++) { int a, b; ll c; cin >> a >> b >> c; d.addEdge(a, b, c); }

  cout << d.calc(0, n - 1) << endl;

  return 0;

}

