typedef long long ll;
const int N = 1e5 + 10;
char s[N];
int n, m, sa[N], rk[N], height[N], t[N], tp[N];
void getsa() {
	for (int i = 1; i <= m; i++) t[i] = 0;
	for (int i = 1; i <= n; i++) t[rk[i] = s[i]]++;
	for (int i = 2; i <= m; i++) t[i] += t[i - 1];
	for (int i = n; i >= 1; i--) sa[t[rk[i]]--] = i;
	for (int w = 1; w <= n; w <<= 1) {
		int num = 0;
		for (int i = n - w + 1; i <= n; i++) tp[++num] = i;
		for (int i = 1; i <= n; i++) if (sa[i] > w) tp[++num] = sa[i] - w;
		for (int i = 1; i <= m; i++) t[i] = 0;
		for (int i = 1; i <= n; i++) t[rk[i]]++;
		for (int i = 2; i <= m; i++) t[i] += t[i - 1];
		for (int i = n; i >= 1; i--) sa[t[rk[tp[i]]]--] = tp[i];
		std::swap(rk, t);
		rk[sa[1]] = num = 1;
		for (int i = 2; i <= n; i++) {
			if (t[sa[i]] == t[sa[i - 1]] && t[sa[i] + w] == t[sa[i - 1] + w]) rk[sa[i]] = num;
			else rk[sa[i]] = ++num;
		}
		if (num == n) break;
		m = num;
	}
}
void getheight() {
	for (int i = 1; i <= n; i++) rk[sa[i]] = i;
	for (int i = 1, k = 0; i <= n; i++) {
		if (rk[i] == 1) continue;
		if (k) k--;
		int j = sa[rk[i] - 1];
		while (s[i + k] == s[j + k]) k++;
		height[rk[i]] = k;
	}
}
int main() {
	scanf("%s", s + 1);
	n = strlen(s + 1);
	m = 128;
	getsa();
	getheight();
	ll ans = 0;
	for (int i = 1; i <= n; i++) ans += n - sa[i] - height[i];
	printf("%lld\n", ans);
	return 0;
}

