const int N = 1e5 + 10;
int n, m, cnt, ans;
int sa[N], rk[N], height[N], t[N], t2[N], c[N];

void getsa(char *s, int n, int m) {
    for (int i = 0; i < m; i++) c[i] = 0;
    for (int i = 0; i < n; i++) c[t[i] = s[i]]++;
    for (int i = 1; i < m; i++) c[i] += c[i - 1];
    for (int i = n - 1; i >= 0; i--) sa[--c[t[i]]] = i;
    for (int k = 1; k <= n; k <<= 1) {
        int num = 0;
        for (int i = n - k; i < n; i++) t2[++num] = i;
        for (int i = 0; i < n; i++) if (sa[i] >= k) t2[++num] = sa[i] - k;
        for (int i = 0; i < m; i++) c[i] = 0;
        for (int i = 0; i < n; i++) c[t[i]]++;
        for (int i = 1; i < m; i++) c[i] += c[i - 1];
        for (int i = n - 1; i >= 0; i--) sa[--c[t[t2[i]]]] = t2[i];
        swap(t, t2);
        t[sa[0]] = 0;
        num = 1;
        for (int i = 1; i < n; i++)
            t[sa[i]] = t[sa[i - 1]] + (t2[sa[i]] != t2[sa[i - 1]] || t2[sa[i] + k] != t2[sa[i - 1] + k]);
        if (num == n) break;
        m = num;
    }
}

void getheight(char *s, int n) {
    for (int i = 0; i < n; i++) rk[sa[i]] = i;
    for (int i = 0, k = 0; i < n; i++, k ? k-- : 0) {
        if (rk[i] == 0) continue;
        int j = sa[rk[i] - 1];
        while (s[i + k] == s[j + k]) k++;
        height[rk[i]] = k;
    }
}

int main() {
    char s[N];
    scanf("%s", s);
    n = strlen(s);
    getsa(s, n, 128);
    getheight(s, n);
    for (int i = 1; i < n; i++) ans += n - sa[i] - height[i];
    printf("%d\n", ans);
    return 0;
}

