		for (int i = 1; i <= n; ++i) if (sa[i] > w) t[++num] = sa[i] - w;
		for (int i = 1; i <= m; ++i) c[i] = 0;
		for (int i = 1; i <= n; ++i) ++c[rk[t[i]]];
		for (int i = 2; i <= m; ++i) c[i] += c[i - 1];
		for (int i = n; i >= 1; --i) sa[c[rk[t[i]]]--] = t[i];
		std::swap(rk, t2);
