void get_SA(int m) {
  for (int i = 1; i <= m; ++i) c[i] = 0;
  for (int i = 1; i <= n; ++i) c[rk[i]]++;
  for (int i = 1; i <= m; ++i) c[i] += c[i - 1];
  for (int i = n; i >= 1; --i) sa[c[rk[t[i]]]--] = t[i];
  for (int i = 1; i <= n; ++i) t2[i] = rk[sa[i]];
  for (int i = 1; i <= n; ++i) rk[i] = t2[i];
}

void DA(int m) {
  for (int i = 1; i <= n; ++i) t[i] = s[i - 1], rk[i] = s[i - 1];
  get_SA(m);
  for (int w = 1, p = 0; p < n; m = p, w <<= 1) {
    p = 0;
    for (int i = 1; i <= w; ++i) t[++p] = n - i + 1;
    for (int i = 1; i <= n; ++i) if (sa[i] > w) t[++p] = sa[i] - w;
    get_SA(m);
    std::swap(t, rk);
    rk[sa[1]] = 1;
    for (int i = 2; i <= n; ++i) {
      rk[sa[i]] = rk[sa[i - 1]];
      if (t[sa[i]] != t[sa[i - 1]] || t[sa[i] + w] != t[sa[i - 1] + w])
        rk[sa[i]]++;
    }
  }
}

void getHeight() {
  for (int i = 1; i <= n; ++i) c[sa[i]] = i;
  for (int i = 1, k = 0; i <= n; ++i) {
    if (k) k--;
    int j = sa[c[i] - 1];
    while (s[i + k] == s[j + k]) k++;
    height[c[i]] = k;
  }
}

