#include <cstdio>

#include <cstring>

#include <algorithm>

using namespace std;

const int N = 5005;

const int M = 50005;

const int INF = 0x3f3f3f3f;

int head[N], nxt[M], to[M], cap[M], ecnt;

void add_edge(int u, int v, int w)

{

    to[++ecnt] = v;

    cap[ecnt] = w;

    nxt[ecnt] = head[u];

    head[u] = ecnt;

}

void add_arc(int u, int v, int w)

{

    add_edge(u, v, w);

    add_edge(v, u, 0);

}

int n, m, s, t;

int dist[N], cur[N];

bool bfs()

{

    memset(dist, 0, sizeof(dist));

    dist[s] = 1;

    int fr = 0, re = 1;

    int que[N];

    que[0] = s;

    while (fr < re)

    {

        int u = que[fr++];

        for (int i = head[u]; i; i = nxt[i])

        {

            int v = to[i];

            if (dist[v] || cap[i] <= 0) continue;

            dist[v] = dist[u] + 1;

            que[re++] = v;

        }

    }

    return dist[t];

}

int dfs(int u, int flow)

{

    if (u == t) return flow;

    int res = 0;

    for (int &i = cur[u]; i; i = nxt[i])

    {

        int v = to[i];

        if (dist[v] != dist[u] + 1 || cap[i] <= 0) continue;

        int tmp = dfs(v, min(flow, cap[i]));

        flow -= tmp;

        res += tmp;

        cap[i] -= tmp;

        cap[i ^ 1] += tmp;

        if (flow == 0) break;

    }

    return res;

}

int dinic()

{

    int res = 0;

    while (bfs())

    {

        memcpy(cur, head, sizeof(head));

        res += dfs(s, INF);

    }

    return res;

}

int main()

{

    scanf("%d%d", &n, &m);

    s = 0, t = n - 1;

    for (int i = 1; i <= m; i++)

    {

        int u, v, w;

        scanf("%d%d%d", &u, &v, &w);

        add_arc(u, v, w);

    }

    printf("%d\n", dinic());

    return 0;

}

